<?php
require __DIR__.'/ui.php';role(['admin','gerente','entregador']);$p=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("UPDATE deliveries SET status=?,driver_id=? WHERE id=?")->execute([$_POST['status'],current_user()['role']==='entregador'?current_user()['id']:($_POST['driver_id']?:null),$_POST['id']]);$os=$p->prepare("SELECT order_id FROM deliveries WHERE id=?");$os->execute([$_POST['id']]);$orderId=(int)$os->fetchColumn();if($_POST['status']==='Entregue')$p->prepare("UPDATE orders SET status='Entregue' WHERE id=?")->execute([$orderId]);timeline_event($orderId,'delivery','Entrega atualizada','Status da entrega: '.$_POST['status']);go('deliveries.php');}
$drivers=$p->query("SELECT id,name FROM users WHERE active=1 AND role='entregador'")->fetchAll();$rows=$p->query("SELECT d.*,o.number,o.delivery_date,o.delivery_time,o.recipient_name,o.recipient_phone,o.delivery_address,u.name driver FROM deliveries d JOIN orders o ON o.id=d.order_id LEFT JOIN users u ON u.id=d.driver_id ORDER BY o.delivery_date,o.delivery_time")->fetchAll();page_head('Entregas');?>
<div class="card"><div class="table"><table><tr><th>Data</th><th>Pedido</th><th>Destinatário</th><th>Telefone</th><th>Endereço</th><th>Entregador</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['delivery_date'])?> <?=e($r['delivery_time'])?></td><td><?=e($r['number'])?></td><td><?=e($r['recipient_name'])?></td><td><?=e($r['recipient_phone'])?></td><td><?=e($r['delivery_address'])?></td><td><?=e($r['driver']?:'-')?></td><td><?=e($r['status'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><?php if(current_user()['role']!=='entregador'):?><select name="driver_id"><option value="">Sem responsável</option><?php foreach($drivers as $d):?><option value="<?=$d['id']?>" <?=$r['driver_id']==$d['id']?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select><?php else:?><input type="hidden" name="driver_id" value="<?=current_user()['id']?>"><?php endif;?><select name="status"><option>Pendente</option><option <?=$r['status']==='Em rota'?'selected':''?>>Em rota</option><option <?=$r['status']==='Entregue'?'selected':''?>>Entregue</option></select><button>Salvar</button></form></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>